import { sql } from 'drizzle-orm';
import { boolean, char, datetime, index, mysqlTable, text, uniqueIndex, varchar } from 'drizzle-orm/mysql-core';

/*
 * Accounts: Better Auth's four tables (see modules/auth/auth.ts).
 *
 * Better Auth reads and writes these through its Drizzle adapter, so the
 * property names (`emailVerified`, `userId`, …) are the ones it expects; the
 * columns are snake_case like every other table. Ids are UUIDv7, generated by
 * `lib/ids.ts` (Better Auth is told to use it).
 *
 * App data that belongs to a person (favourites, collections) references
 * `users.id` with ON DELETE CASCADE, so deleting the user removes it all.
 * Nothing outside the auth module reads `sessions`, `accounts` or
 * `verifications`.
 */

const timestamps = {
  createdAt: datetime({ fsp: 3 })
    .notNull()
    .default(sql`(CURRENT_TIMESTAMP(3))`),
  updatedAt: datetime({ fsp: 3 })
    .notNull()
    .default(sql`(CURRENT_TIMESTAMP(3))`)
    .$onUpdate(() => new Date()),
};

export const users = mysqlTable('users', {
  id: char({ length: 36 }).primaryKey(),
  name: varchar({ length: 150 }).notNull(),
  email: varchar({ length: 255 }).notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  /** Profile photo URL from Apple/Google. */
  image: varchar({ length: 1024 }),
  ...timestamps,
});

/** One row per signed-in device. The app sends `token` (in the session cookie) with each request. */
export const sessions = mysqlTable(
  'sessions',
  {
    id: char({ length: 36 }).primaryKey(),
    userId: char({ length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    token: varchar({ length: 255 }).notNull().unique(),
    expiresAt: datetime({ fsp: 3 }).notNull(),
    ipAddress: varchar({ length: 64 }),
    userAgent: varchar({ length: 512 }),
    ...timestamps,
  },
  (table) => [index('sessions_user_id_idx').on(table.userId)],
);

/**
 * How a user signs in: one row per method. `providerId` is `credential`
 * (email + password, hashed in `password`), `apple` or `google`.
 */
export const accounts = mysqlTable(
  'accounts',
  {
    id: char({ length: 36 }).primaryKey(),
    userId: char({ length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    providerId: varchar({ length: 32 }).notNull(),
    /** The provider's id for the person (Apple `sub`, Google `sub`); the user id for `credential`. */
    accountId: varchar({ length: 255 }).notNull(),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: datetime({ fsp: 3 }),
    refreshTokenExpiresAt: datetime({ fsp: 3 }),
    scope: varchar({ length: 512 }),
    password: varchar({ length: 255 }),
    ...timestamps,
  },
  (table) => [
    index('accounts_user_id_idx').on(table.userId),
    // Sign-in finds the account by provider and the provider's id for the person.
    uniqueIndex('accounts_provider_account_unique').on(table.providerId, table.accountId),
  ],
);

/** Short-lived tokens (password reset links, OAuth state). */
export const verifications = mysqlTable(
  'verifications',
  {
    id: char({ length: 36 }).primaryKey(),
    identifier: varchar({ length: 255 }).notNull(),
    value: text().notNull(),
    expiresAt: datetime({ fsp: 3 }).notNull(),
    ...timestamps,
  },
  (table) => [index('verifications_identifier_idx').on(table.identifier)],
);
